import random

def transform(grid):
    """Double the grid; retain the original and add three stable permutations."""
    h, w = len(grid), len(grid[0])
    cells = [v for row in grid for v in row]
    rng = random.Random(0)
    tiles = [[row[:] for row in grid]]
    for _ in range(3):
        shuffled = cells[:]
        rng.shuffle(shuffled)
        tiles.append([shuffled[r*w:(r+1)*w] for r in range(h)])
    out = []
    for top in (0, 2):
        for r in range(h):
            out.append(tiles[top][r] + tiles[top+1][r])
    return out

if __name__ == '__main__':
    test = [[0,9,3,3,1,5],[7,5,3,3,1,7],[3,3,3,3,9,2],[2,4,0,7,3,3],[4,3,5,3,3,3],[3,3,3,3,3,3]]
    for row in transform(test): print(row)
